      "args_json": "[[5, 5, 5, 5], 1]",
      "expected_json": "[5]",
      "note": "All elements identical, k=1."
    },
    {
      "args_json": "[[1, 2, 3, 4, 5], 5]",
      "expected_json": "[5, 4, 3, 2, 1]",
      "note": "k equals the number of distinct elements."
    },
